class Pool:
    def __init__(self, size, factory):
        self._idle = queue.LifoQueue(maxsize=size)
        for _ in range(size): self._idle.put(factory())

    @contextmanager
    def acquire(self, timeout=5):
        obj = self._idle.get(timeout=timeout)   # queue.Empty when exhausted
        try: yield obj
        finally:
            obj.reset(); self._idle.put(obj)
